#include "../CODEC.H"
int codec_encode_utf8(U32 c,unsigned char*out,unsigned int*n){if(c<=0x7F){out[0]=(unsigned char)c;*n=1;}else if(c<=0x7FF){out[0]=(unsigned char)(0xC0|(c>>6));out[1]=(unsigned char)(0x80|(c&63));*n=2;}else if(c<=0xFFFF&&!(c>=0xD800&&c<=0xDFFF)){out[0]=(unsigned char)(0xE0|(c>>12));out[1]=(unsigned char)(0x80|((c>>6)&63));out[2]=(unsigned char)(0x80|(c&63));*n=3;}else if(c<=0x10FFFF){out[0]=(unsigned char)(0xF0|(c>>18));out[1]=(unsigned char)(0x80|((c>>12)&63));out[2]=(unsigned char)(0x80|((c>>6)&63));out[3]=(unsigned char)(0x80|(c&63));*n=4;}else return 0;return 1;}
